    "searchText": "codepotx workflow evaluate the official javascript rewrite using typed authoring, handlebars packs, codepotfile.yml, and the codepotx runtime. codepotx workflow this guide describes the official javascript rewrite currently developed inside the monorepo. 1. prepare the workspace bash corepack enable pnpm install pnpm --filter codepotx check pnpm --filter codepotx-cli check 2. create codepotx.config.ts ts import definecodepotconfig, defineversioncontract, z, from 'codepotx'; const v1 = defineversioncontract info: title: 'example', version: '1.0.0' , ; const schemas = v1.defineschemas user: id: z.string .uuid , email: z.string .email , , ; const users = v1.defineresource name: 'users', route: '/users', ; users.defineroutes .routes route = listusers: route.get '/' .response schemas.ref.user.array , ; export default definecodepotconfig contracts: v1 ; 3. create a handlebars pack text templates/typescript/ ├── paths.yaml ├── partials/ └── model / model.name.kebab .ts.hbs example paths.yaml : yaml name: typescript-models version: 1.0.0 folders: model: select: schemas.models as: model mode: each parts: - src - models example template: handlebars export interface model.name.pascal each model.fields name.camel : lang.type ; /each 4. create codepotfile.yml yaml allow: true tasks: sdk: authoring: ./codepotx.config.ts templates: ./templates/typescript output: ./src/generated clean: models transactional: true 5. inspect before generating bash codepotx validate codepotx variables sdk codepotx plan sdk --json codepotx generate sdk --dry-run 6. generate bash codepotx generate sdk the runtime plans and renders before mutation, applies managed writes, updates the task manifest, runs approved commands, and returns structured diagnostics and reports. 7. embed the runtime ts import createdefaultcodepotruntime from 'codepotx/runtime'; const runtime = createdefaultcodepotruntime projectroot: process.cwd , ; const response = await runtime.execute kind: 'generation.execute', input: task: 'sdk' , ; the same runtime call can sit behind a cli, web page, editor command, mcp tool, or internal service."
